{"path": "zipper.py", "content": "class Zipper:
    """Zipper over a binary tree of dicts: {"value": v, "left": t|None, "right": t|None}.

    The focus is a subtree; `path` holds breadcrumbs from the focus up to the root.
    Each breadcrumb is (direction, parent_value, other_subtree).
    """

    def __init__(self, focus, path=()):
        self._focus = focus
        self._path = path

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, ())

    def value(self):
        return self._focus["value"]

    def set_value(self, value):
        return Zipper(dict(self._focus, value=value), self._path)

    def left(self):
        child = self._focus["left"]
        if child is None:
            return None
        crumb = ("left", self._focus["value"], self._focus["right"])
        return Zipper(child, (crumb,) + self._path)

    def set_left(self, tree):
        return Zipper(dict(self._focus, left=tree), self._path)

    def right(self):
        child = self._focus["right"]
        if child is None:
            return None
        crumb = ("right", self._focus["value"], self._focus["left"])
        return Zipper(child, (crumb,) + self._path)

    def set_right(self, tree):
        return Zipper(dict(self._focus, right=tree), self._path)

    def up(self):
        if not self._path:
            return None
        (direction, value, other), rest = self._path[0], self._path[1:]
        if direction == "left":
            parent = {"value": value, "left": self._focus, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._focus}
        return Zipper(parent, rest)

    def to_tree(self):
        zipper = self
        while zipper._path:
            zipper = zipper.up()
        return zipper._focus

    def __eq__(self, other):
        if not isinstance(other, Zipper):
            return NotImplemented
        return self._focus == other._focus and self._path == other._path
